rss.channel:
{{ .Site.Title }}
{{ .Site.BaseURL }}
{{ with .Site.Params.description }}{{ . }}{{ end }}
Hugo
{{ .Site.LanguageCode }}
{{ .Site.Params.author }}
{{ .Site.Params.author }}
{{ with .Site.Copyright }}{{ . }}{{ end }}

{{ range first 20 (where .Site.RegularPages "Section" "posts") }}


  {{ .Title }}
  {{ .Permalink }}
  {{ .Permalink }}
  {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" }}
  {{ with .Params.categories }}{{ index . 0 }}{{ end }}
  {{ range .Params.tags }}{{ . }}
  {{ end }}

    {{ if .Params.encrypted }}
    <p>🔒 这篇文章已加密，请前往网站查看。</p>
    <p><a href="{{ .Permalink }}">点击阅读 →</a></p>
    {{ else }}
    {{ `` | safeHTML }}
    {{ if .Summary }}
    {{ .Summary | plainify | truncate 200 }}
    {{ else }}
    {{ .Plain | truncate 200 }}
    {{ end }}
    &lt;p&gt;&lt;a href="{{ .Permalink }}"&gt;阅读全文 →&lt;/a&gt;&lt;/p&gt;
    {{ `` | safeHTML }}
    {{ end }}


{{ end }}
